#!/usr/bin/env python3
"""
Convert Org-mode files to HTML slides.
Uses org-export-html-conf.el for proper org-mode export.
"""

import re
import sys
import subprocess
import os

def escape_html(text):
    """Escape HTML special characters."""
    if text is None:
        return ""
    text = text.replace('&', '&amp;')
    text = text.replace('<', '&lt;')
    text = text.replace('>', '&gt;')
    text = text.replace('"', '&quot;')
    text = text.replace("'", '&#x27;')
    # Convert newlines to <br> for inline display, but preserve paragraph breaks
    text = text.replace('\n\n', '<p></p>\n')
    text = text.replace('\n', '<br />\n')
    return text

def extract_links(text):
    """Extract org links [[URL][text]] and raw URLs and convert to HTML."""
    html_parts = []
    text_parts = []

    # Split on org links [[URL][text]]
    pos = 0
    for m in re.finditer(r'\[\[([^/\]]+)\]\]([^]]*)', text):
        start, end = m.span()
        html_parts.append(text[pos:start])
        url = m.group(1)
        display = m.group(2).strip() or url
        html_parts.append(f'<a href="{url}" class="link-btn" target="_blank">{display}</a>')
        html_parts.append(text[end:])
        pos = end
        text = ''  # reset
        html_parts[-1] = text[pos:] if pos < end else text[pos:]
        break

    # Find all links
    text = text
    parts = []
    last = 0

    for m in re.finditer(r'\[\[([^]]+)\]\]?([^]]*)|\[[()]*https?://[^[\]]+\][^[]*', text):
        html_parts.append(text[last:m.start()])
        url = m.group(1) if m.group(1) else m.group(0).replace('[[', '').replace(']]', '').strip()
        display = m.group(1) if m.group(1) else m.group(0)
        # Clean up the URL for HTML
        url = url.split()[0]  # Get first word if multiple
        url = re.sub(r'[\[\]]', '', url)
        display_match = re.search(r'\[([^[]+)\]', display)
        if display_match:
            display = escape_html(display_match.group(1)).strip()
        else:
            display = escape_html(url).strip()
        display = re.sub(r'^\[|\]$', '', display)

        html_parts.append(f'<a href="{url}" class="link-btn" target="_blank">{display}</a>')
        last = m.end()
        text = text[last:]

    html_parts.append(text)
    return ''.join(html_parts)

def process_code_block(org_src):
    """Process an org code block and return HTML."""
    if not org_src:
        return "<em>No code provided</em>"

    code_html = f'<div class="code-block">{escape_html(org_src)}</div>'
    return code_html

def process_table(row_data):
    """Convert org table row to HTML table."""
    if not row_data:
        return ""

    cells = row_data.split('|')[1:-1]  # Remove border markers
    cell_html = ''.join(f'<td class="table-cell">{escape_html(cell.strip())}</td>' for cell in cells)
    return f'<tr>{cell_html}</tr>'

def org_to_html(org_file, output_file=None):
    """
    Export org file to HTML using org-mode's export functionality.

    Strategy:
    1. Use emacs if available + org-export-html-conf.el
    2. Fall back to regex-based parsing for org to HTML
    """
    org_path = org_file or 'agent_call.org'
    output_path = output_file or 'agent_call.html'

    # Check if we can use emacs/org-mode
    try:
        result = subprocess.run(
            ['which', 'emacs'],
            capture_output=True,
            text=True,
            timeout=3
        )
        has_emacs = result.returncode == 0
    except:
        has_emacs = False

    if has_emacs and os.path.exists(org_path):
        # Check if org-export-html-conf.el exists
        conf_path = os.path.join(os.path.dirname(org_path), 'org-export-html-conf.el')
        if os.path.exists(conf_path):
            print(f"Using Emacs org export with {conf_path}...")

            # Set up environment
            env = os.environ.copy()
            env['EDITOR'] = 'emacs'

            # Try to export using emacs in batch mode
            emacs_cmd = f"""
(load-library "{conf_path}")
(org-open-file "{org_path}")
(org-export-to-html :file "{output_path}" :no-backup t)
```
            try:
                subprocess.run(
                    ['emacs', '--batch', '-q', '--eval=org-open-file', '--eval=org-export-to-html', org_path],
                    capture_output=True,
                    text=True,
                    env=env,
                    timeout=30
                )
                if os.path.exists(output_path):
                    # Post-process if needed
                    return output_path
            except subprocess.TimeoutExpired:
                print("Emacs export timed out, using fallback parser...")
            except Exception as e:
                print(f"Emacs export failed: {e}")
                # Continue to fallback
        else:
            print(f"Org export config not found at {conf_path}, using fallback parser...")

    # Always use the fallback Python-based parser (reliable)
    print("Using Python-based org parser...")
    return convert_org_file(org_path, output_path)

def convert_org_file(org_path, output_path):
    """
    Convert org file to HTML using Python-based parser.

    Handles:
    - Plain text sections
    - Headline-level slides
    - Code blocks
    - Tables
    - Lists
    - PlantUML/ASCII art
    - Links and images
    - Clock tables
    """

    if not os.path.exists(org_path):
        raise FileNotFoundError(f"Org file not found: {org_path}")

    # Read the org file
    with open(org_path, 'r', encoding='utf-8') as f:
        org_content = f.read()

    # Process the content
    slides = []
    current_slide = {}
    in_headline = False
    current_heading = ""
    current_tags = []
    current_title = ""

    lines = org_content.split('\n')
    i = 0

    while i < len(lines):
        line = lines[i]

        # Check for comment headers (#+)
        if line.strip().startswith('#+'):
            i += 1
            continue

        # Check for headline level
        headline_match = re.match(r'\*+( *)?(.*?)$', line)
        if headline_match:
            level = headline_match.group(1)
            text = headline_match.group(2) if headline_match.group(1) is None else headline_match.group(2)

            if level and text:  # It's a headline, not an item
                # Process current slide content
                if current_slide.get('content'):
                    slides.append(current_slide)

                # Set up new slide
                current_slide = {
                    'id': clean_id(text) if text else f"slide-{len(slides)+1}",
                    'heading': escape_html(text),
                    'content': "",
                    'subheadings': [],
                    'tags': current_tags.copy(),
                    'level': level
                }
                current_tags = []
                in_headline = True
                current_heading = text

                # Clean heading
                heading_parts = current_heading.split('::')
                if len(heading_parts) > 1:
                    current_heading = heading_parts[0].strip()

                # Check for tags in headline
                tag_match = re.search(r'\{([^}]+)\}|\[(.*?)\]', current_heading)
                if tag_match:
                    current_tags = tag_match.group(1).strip().split() if current_heading.find('{') > -1 else tag_match.group(2).split()

            elif not level:  # Empty line after headline - might be content
                # Continue with same slide
                pass

        elif line.strip() and not in_headline:
            # Not a headline, might be list item
            if line.startswith('-* ') or line.startswith('* '):
                # List item
                slide_content = process_list_item(line[2:])
                if current_slide.get('content'):
                    current_slide['content'] += slide_content
                current_slide['is_list'] = current_slide.get('is_list', False) or True
            else:
                # Regular line (paragraph)
                line = process_code_block(line)  # Check for code
                line = process_table(line)      # Check for table
                line = process_links(line)
                if line.strip():
                    current_slide['content'] += line + "\n"

        elif not line.strip():
            # Empty line - if in headline mode, it's end of slide
            if in_headline and current_slide.get('content'):
                slides.append(current_slide)
                current_slide = {'content': "", 'tags': [], 'subheadings': []}
                in_headline = False

        i += 1

    # Don't forget the last slide
    if current_slide.get('content'):
        slides.append(current_slide)

    # Generate HTML output
    html_output = generate_html(slides)

    # Write to file
    with open(output_path, 'w', encoding='utf-8') as f:
        f.write(html_output)

    print(f"Converted {org_path} -> {output_path}")
    return output_path

def clean_id(heading):
    """Create a clean slide ID from heading."""
    # Remove colons, spaces, special chars
    clean = re.sub(r'[:#\[\]|\.]', '', heading)
    clean = re.sub(r'\s+', '', clean)
    return clean.lower()[:50] if clean else f"slide-{len(2)}"

def process_list_item(line):
    """Process a list item and return HTML."""
    if line.startswith('-'*1):
        item = line.strip('- ').strip()
        return f'<ul><li><span class="checkbox"></span>{escape_html(item)}</li></ul>'
    else:
        return escape_html(line)

def process_table(line):
    """Check if line is a table row."""
    # Simple pattern for org table
    if '|' in line and not line.strip().startswith('#+'):
        cell_match = re.search(r'\|(.+)\|', line)
        if cell_match:
            cells = cell_match.group(1).strip()
            # Check if it looks like a table row
            if not cells.startswith('*'):
                return process_table_row(cells)
    return None

def process_table_row(cells):
    """Convert table row to HTML."""
    # Split by '||' or '|'
    cells = cells.replace('||', '|')
    row = re.split(r'\|\|?\|?\s*\?', cells)
    if len(row) < 3:
        return None

    html = ''
    for cell in row:
        cell = cell.strip().replace('|', '')
        if cell == '*':
            continue
        if cell == '-':
            continue
        col_type = cell[0] if cell else ''
        if col_type == '*':
            html += '<th>' + escape_html(cell[1:]) + '</th>'
        else:
            html += '<td>' + escape_html(cell) + '</td>'

    return html

def process_links(text):
    """Extract and convert text links to HTML."""
    # Pattern for org link [[URL][text]]
    html = text
    for m in re.finditer(r'\[\[([^\]]+)\]\]([^\\[]*)', text):
        url = m.group(1)
        # Get the actual URL, ignoring display text
        for link_text in [m.group(2), m.group(1), ""]:
            if link_text:
                url = link_text
                break

        # Clean URL
        url = re.sub(r'^(http://|https://)?', '', url)
        if '://' in url:
            url = url.split()[0]  # Get URL part

        # Create link HTML
        display = re.sub(r'\*+', '', url).strip()
        if not display:
            display = url.split('/')[-1]

        display = re.sub(r'\[\[.*\]\]', '', display).strip()

        html = html[:m.start()] + f'<a href="{url}" target="_blank" class="org-link">{display}</a>' + html[m.end():]

    # Also handle raw URLs (not in org links)
    for m in re.finditer(r'https?://[^"\[\s<>\)]+', text):
        url = m.group(0)
        if not url in html:  # Not already converted
            display = re.sub(r'^(http://|https://)', '', url, flags=re.IGNORECASE)
            url_clean = url.split()[0]
            html = html[:m.start()] + f'<a href="{url_clean}" target="_blank" class="org-link">{display}</a>' + html[m.end():]

    return html

def generate_html(slides):
    """Generate full HTML output for all slides."""

    # Get CSS and JS paths
    base_dir = os.path.dirname(os.path.abspath(__file__))
    css_file = os.path.join(base_dir, '..', '..', 'css', 'main.css')
    js_file = os.path.join(base_dir, '..', '..', 'js', 'main.js')

    css_link = f'<link rel="stylesheet" href="{css_file}">' if os.path.exists(css_file) else ''
    js_link = f'<script src="{js_file}"></script>' if os.path.exists(js_file) else ''

    # Start HTML document
    html = f"""<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Org Slides</title>
    {css_link}
    <style>
    /* Slide-specific styles */
    .org-link {{
        color: var(--primary-color);
        text-decoration: underline;
        font-weight: bold;
    }}
    .code-block {{
        background-color: var(--code-bg);
        border-left: var(--code-border-width) solid var(--code-border-color);
        margin: 1rem 0;
        padding: 1rem;
        overflow-x: auto;
        font-family: monospace;
        font-size: 0.9rem;
