        is_subslide = ' subslide' if slide.get('level', 0) > 1 else ''
        heading_size = '3rem' if not slide.get('is_list', False) else '2rem'

        html += f"""
<div class="slide{is_subslide}" id="{slide['id']}" data-level='{slide.get('level', 1)}'>
    <{heading_level} style="font-size: {heading_size};">{slide['heading']}</{heading_level}>
"""

        # Content
        if slide['content'].strip():
            content_lines = slide['content'].split('\n')
            for line in content_lines:
                line = line.strip()
                if line:
                    # Check if it's a bullet point
                    if line.startswith('-* ') or line.startswith('* '):
                        item_text = line[2:].strip()
                        html += f"""
