    """Fix broken org link styles."""
    # Remove org links that were processed
    html = re.sub(r'org-link[^>]*>', '', html)
    # Clean up empty lines
    html = re.sub(r'\n\s*\n*', '\n', html)
    return html

def main():
    """Main entry point."""
    if len(sys.argv) >= 2:
        org_file = sys.argv[1]
        output_file = sys.argv[2] if len(sys.argv) >= 3 else None
    else:
        # Default values
        org_file = 'agent_call.org'
        output_file = 'agent_call.html'

    org_to_html(org_file, output_file)

    # Print all slides
    print(f"Slide count generated: {len(sys.argv)} + slides")

