def generate_base_html(org_path, output_path=None):
    """Generate full HTML document with proper org parsing."""

    css = generate_css()

    # Read org file
    if not os.path.exists(org_path):
        print(f"[Error] File not found: {org_path}", file=sys.stderr)
        return None

    with open(org_path, 'r', encoding='utf-8') as f:
        org_content = f.read()

    # Check for Emacs org export config
    conf_path = os.path.join(os.path.dirname(org_path), 'org-export-html-conf.el')
    if os.path.exists(conf_path):
        print(f"[ℹ] Found Emacs org config, but using Python parser")

    # Parse content
    slides = parse_org_content(org_content)

    # Generate HTML
    if slides is None:
        print("[Warning] No slides parsed", file=sys.stderr)
        return None

    slide_html = generate_slides_html(slides)

    # Prepare CSS/JS links
    base_dir = os.path.dirname(os.path.abspath(__file__))
    css_file = os.path.join(base_dir, '..', '..', 'css', 'main.css')
    js_file = os.path.join(base_dir, '..', '..', 'js', 'main.js')

    css_link = f'<link rel="stylesheet" href="{css_file}">' if os.path.exists(css_file) else ''
    js_link = f'<script src="{js_file}"></script>' if os.path.exists(js_file) else ''

    # Assemble full document
    doc = f'''<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <meta name="description" content="Org Slides">
    <title>{org_file}: Org Slides</title>
    {css_link}
    {js_link}
    <style>{css}</style>
</head>
<body>
<div class="slides-container">
    {slide_html}
</div>

<footer class="footer">
    <button id="button-prev" class="nav-button">Previous</button>
    <button id="button-next" class="nav-button">Next</button>
    <button id="button-toc" class="nav-button">TOC</button>
