</footer>
</body>
</html>'''

    return doc


def parse_org_content(content):
    """Parse org content into slide objects."""
    slides = []
    current_slide = None
    in_list_context = True
    slide_id_counter = 0

    lines = content.split('\n')

    for line in lines:
        # Skip org special syntax
        if line.strip().startswith('#+') or line.strip().startswith('\\'):
            continue

        # Remove trailing comments
        if '--->' in line:
            line = line.split('--->', 1)[0].rstrip()

        # Skip empty lines in list context
        if line.strip() == '' and in_list_context:
            continue

        # Check for level-1 headline (*Slide Title *)
        match = re.match(r'^\*+[^*]+.*$', line.strip().rstrip('*'))
        if match and not line.startswith('*Slide '):
            # Found a new slide section
            old_slide = current_slide
            current_slide = {
                'id': f'slide-{slide_id_counter}',
                'heading': match.group(0),
                'content': []
            }
            slides.append(current_slide)
            in_list_context = True
            slide_id_counter += 1
            continue

        # If we had a previous slide and this is content
        if current_slide:
            # List item
            if '- [' in line or '-*' in line or '* ' in line:
                content = re.sub(r'^\s*[-*]', '', line.strip())
                current_slide['content'].append(content)
            continue

    return slides


def generate_slides_html(slides):
    """Generate slide HTML content."""

    html = ""

    for idx, slide in enumerate(slides):
        heading_text = slide.get('heading', f'Slide {idx+1}')
        slide_id = slide.get('id', f'slide-{idx}')

        html += f'<div class="slide" id="{slide_id}">\n'
        html += f'    <h2>{render_heading(heading_text)}</h2>\n'

        content = slide.get('content', [])
        if content:
            for item in content:
                item = render_heading(item)
                # Check if it looks like a list item
                if item.strip() and item.startswith('  ') or item.startswith('-') or item.startswith('*'):
                    clean_item = re.sub(r'^\s*[-*]', '', item)
                    html += f'    <ul>\n'
                    html += f'        <li>{escape_html(clean_item)}</li>\n'
                    html += f'    </ul>\n'
                else:
                    html += f'    <p>{escape_html(item)}</p>\n'

        html += f'</div>\n'

    return html


def render_heading(text):
    """Render heading text."""
    if not text:
        return ''

    # Clean up heading
    title = re.sub(r'^\*+', '', text.strip())
    title = title.split('\n')[0]  # Take first line

    # Handle :: format
    if '::' in title:
        match = re.search(r'^[^:]+::([^:]+)', title)
        if match:
            title = match.group(1).strip()

    return escape_html(title)


def escape_html(text):
    """Escape HTML special characters."""
    if not text:
        return ''

    text = str(text)
    for char, escape in [('&', '&amp;'), ('<', '&lt;'), ('>', '&gt;'), ('"', '&quot;'), ("'", '&#x27;')]:
        text = text.replace(char, escape)

    return text


def convert_org_to_html(org_file='agent_call.org', html_file='agent_call.html'):
    """Main function to convert org to HTML."""

    full_path = os.path.abspath(org_file)
    html_path = os.path.abspath(html_file)

    print(f"[*] Converting: {org_file}")

    if not os.path.exists(full_path):
        print(f"[Error] File not found: {full_path}", file=sys.stderr)
        return None

    # Generate HTML
    full_html = generate_base_html(full_path, html_path)

    if full_html:
        with open(html_path, 'w', encoding='utf-8') as f:
            f.write(full_html)

        print(f"[✓] Generated: {html_path}")
        print(f"[ℹ]   Total slides: {len(slides) if 'slides' in locals() else 'N/A'}")
        return html_path

    return None


if __name__ == '__main__':
    import argparse
    parser = argparse.ArgumentParser(description='Convert org files to HTML slides.')
    parser.add_argument('org_file', nargs='?', default='agent_call.org', help='Org file to convert')
    parser.add_argument('-o', '--output', nargs='?', help='Output HTML file (default: {org_file}.html)')

    args = parser.parse_args()

    output = args.output or f"{args.org_file}.html"

    convert_org_to_html(args.org_file, output)
    print(f"[✓] Done!")

